import json, re, math
from collections import Counter
import numpy as np
from scipy.optimize import linear_sum_assignment

exc=json.load(open("/workspace/work/../materials/excerpts.json"))["excerpts"]
turns=json.load(open("/workspace/work/turns_raw.json"))
STOP=set("the a an of to in and or is are be been being for on at by with from as that this these those which who whom whose it its their our your his her they we you i he she them us not no yes do does did done have has had will would shall should can could may might must more most less least than then so such only own same other another each any all both few much many very can cannot into out up down over under again further once here there when where why how what who will just also about against between through during before after above below off no nor too s t re ve ll d m o mr mrs madam president vice commission commissioner colleagues dear thank thanks you very much".split())
def toks(t):
    t=t.lower(); t=re.sub(r"[^a-z ]"," ",t)
    return [w for w in t.split() if len(w)>2 and w not in STOP]
docs=[toks(e["text"]) for e in exc]+[toks(t["text"]) for t in turns]
df=Counter()
for d in docs:
    for w in set(d): df[w]+=1
N=len(docs)
def vec(d):
    c=Counter(d); v={}
    for w,f in c.items(): v[w]=(1+math.log(f))*math.log((N+1)/(df[w]+1))
    n=math.sqrt(sum(x*x for x in v.values())) or 1
    return {w:x/n for w,x in v.items()}
ev=[vec(toks(e["text"])) for e in exc]
tv=[vec(toks(t["text"])) for t in turns]
def cos(a,b):
    if len(a)>len(b): a,b=b,a
    return sum(x*b.get(w,0) for w,x in a.items())
M=len(turns); K=len(exc)
S=np.zeros((M,K))
for i in range(M):
    for j in range(K): S[i,j]=cos(tv[i],ev[j])
blockidx={t["block"]:i for i,t in enumerate(turns)}
excidx={e["excerpt_id"]:j for j,e in enumerate(exc)}
PINS={3:"excerpt_013",7:"excerpt_003",8:"excerpt_019",17:"excerpt_057",24:"excerpt_056",26:"excerpt_076",28:"excerpt_080",32:"excerpt_012",33:"excerpt_044",35:"excerpt_026",36:"excerpt_017",39:"excerpt_025",44:"excerpt_043",47:"excerpt_051",50:"excerpt_082",52:"excerpt_081",55:"excerpt_037",60:"excerpt_058",83:"excerpt_015",84:"excerpt_060",85:"excerpt_031",86:"excerpt_047",91:"excerpt_078",98:"excerpt_023",102:"excerpt_036",108:"excerpt_032",111:"excerpt_027",112:"excerpt_004",118:"excerpt_061",134:"excerpt_034"}
pinned_i=set(); pinned_j=set(); assign={}
for b,eid in PINS.items():
    i=blockidx[b]; j=excidx[eid]; assign[i]=j; pinned_i.add(i); pinned_j.add(j)
free_i=[i for i in range(M) if i not in pinned_i]
free_j=[j for j in range(K) if j not in pinned_j]
sub=S[np.ix_(free_i,free_j)]
ri,cj=linear_sum_assignment(-sub)
for a,b in zip(ri,cj): assign[free_i[a]]=free_j[b]
out=[]
for i,t in enumerate(turns):
    j=assign[i]
    top=sorted(range(K),key=lambda k:-S[i,k])[:4]
    out.append({"block":t["block"],"start":t["start"],"end":t["end"],"dur":t["dur"],
        "excerpt_id":exc[j]["excerpt_id"],"score":round(float(S[i,j]),3),"pinned":t["block"] in PINS,
        "alts":[(exc[k]["excerpt_id"],round(float(S[i,k]),3)) for k in top]})
json.dump(out,open("/workspace/work/match_pinned.json","w"),indent=1)
assert len(set(o["excerpt_id"] for o in out))==86,"not bijection"
print("OK bijection, %d turns"%len(out))
for o in out:
    tag="PIN" if o["pinned"] else "   "
    print("%s b%3d [%s %.2f] alts:%s"%(tag,o["block"],o["excerpt_id"],o["score"],",".join("%s:%.2f"%(a,s) for a,s in o["alts"][:3])))
PYEOF
